import asyncio
import sys
async def render(text):
    await asyncio.sleep(0)
    return text.upper()
async def main(text):
    if text == '__invalid__':
        raise ValueError('invalid job')
    if text == 'cancel':
        task = asyncio.create_task(render('late'))
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            return 'cancelled'
    if not text:
        raise ValueError('text required')
    return await asyncio.wait_for(render(text), timeout=0.1)
print(asyncio.run(main(sys.stdin.read().strip())))

